export function review(lessons){const set=(id,fields)=>{Object.assign(lessons[id],fields);Object.assign(lessons[id].cases[0],fields);};
for(const id of ['vienna','vienna-gambit'])set(id,{purpose:'백은 Nc3로 e4를 지키고 f4로 흑 중앙을 흔들어 활동적인 중앙과 f열 압력을 얻으려 합니다. 흑은 …d5로 중앙을 반격합니다. 대표 교환 후에는 양쪽 폰 수가 같으므로 지속적인 폰 희생 상태가 아니라 비대칭 폰·파일의 미들게임입니다.',structure:lessons[id].structure.replace('代表','대표'),ideas:['f4는 e5를 공격하지만 킹 주변 약화도 있어 중앙 …d5를 먼저 처리합니다.','…d5는 e4를 공격합니다. fxe5 …Nxe4 교환 뒤 백 e5와 흑 d5가 새 거점입니다.','…Nxc3 bxc3는 백 더블 c폰·반열린 b열을 만들고 c3폰은 d4를 지지합니다. 구조 부담과 활동을 함께 봅니다.'],counters:['흑의 …c5: 백 d4 구축을 공격해 e5 거점의 지지를 줄이려 합니다. 백은 중앙 유지·교환 뒤 파일 활동을 선택합니다.','흑의 …f6: e5를 공격해 공간을 줄입니다. 양쪽 킹 안전·되잡기와 열린 f/e열을 계산해야 합니다.']});
set('horwitz',{purpose:'…e6는 고정 구조를 강제하지 않습니다. 백 2.e4에 …d5–…Nf6로 프렌치에 전환한 현재 예시에서 흑은 e4를 압박하고 백 e5 이후 사슬을 공격하려 합니다. 백 c4면 퀸즈 갬빗 등 다른 미들게임입니다.',structure:'현재 백 e4–d4 대 흑 e6–d5 긴장이고 Nf6가 e4를 공격합니다. 백 e5 뒤에만 사슬이 닫혀 …Nfd7–…c5를 준비합니다. 전진 전부터 닫힌 사슬이 존재한다고 하지 않습니다.'});
set('mikenas',{purpose:'흑은 …Nc6로 기물을 먼저 꺼내지만 백 d5에 나이트가 이동해 시간을 내줄 수 있습니다. 백은 d5/e4 공간을 안정시키고 흑은 중앙 폰 반격으로 전개 비용을 보상하려 합니다.',structure:'현재 백 d5/e4 대 아직 움직이지 않은 흑 중앙 폰이며 나이트는 g6에 있습니다. …e5면 닫힌 중앙, …e6 교환이면 반열린 구조로 바뀝니다. 현재 d4–e5 사슬이나 d5 흑 나이트는 없습니다.',pieces:['백: c3 나이트가 d5/e4 공간을 지원합니다. 나머지 왕측 기물을 전개하고 중앙 폰을 지켜 시간 이점을 활동으로 바꿉니다.','흑: g6 나이트는 중앙에 닿는 칸을 다시 찾아야 합니다. 나머지 기물의 전개가 늦어 중앙 반격과 킹 안전을 조율합니다.'],targets:['백: 중앙·전개 지연 → 폰 거점·비숍·나이트 → 공간과 주도권.','흑: d5/e4 기반 → 중앙 폰 돌파·기물 → 공간 감소와 활동.'],plans:[['d5/e4 공간','왕측 기물 전개','중앙 유지 후 e5 등 계산','중앙·흑 전개 지연','중앙 압박 말 교환','중앙 지원 말 보존','안정된 공간과 전개'],['공간 부족·반복 나이트 이동','나이트와 나머지 기물 개선','…e5/…e6/…d6 중 선택','d5/e4','백 공간 활용 말 교환','활성 중앙 말 보존','돌파로 줄어든 공간 차이']]});
set('old-benoni',{structure:'백 c4–d5–e4 대 흑 c5–d6이며 양쪽 e폰이 남습니다. 백 공간에 흑은 …e5로 닫거나 …e6 교환으로 반격합니다. 아직 e열은 닫혀 있고 모던 베노니의 중앙 폰 다수는 e폰 교환 후에만 생깁니다.'});
set('qga',{purpose:'흑은 d폰으로 c4를 잡아 중앙 부담을 줄이고 폰을 반환하며 빠른 전개·…c5 반격을 얻습니다. 백은 회복 후 d4 공간을 유지합니다. 향후 교환으로 고립폰형에 갈 수 있지만 현재는 아닙니다.',structure:'Bxc4 후 백 d4/e3 대 흑 c5/e6이며 폰 수는 같습니다. …cxd4 exd4 이후 백 c/e폰이 없어 d4가 고립됩니다. 지금은 e3가 d4를 지지합니다.'});
set('alapin',{purpose:'c3로 d4 중앙을 준비하고 오픈 시실리안의 나이트 전개 대신 폰 공간을 선택합니다. 흑은 …d5/…Nf6로 즉시 중앙을 시험합니다. c3 나이트 길을 막는 비용과 고립폰 가능성을 함께 다룹니다.',structure:'현재 백 c3–d4 대 흑 c5이고 백 e폰은 교환되었습니다. 흑 퀸은 d5에 있지만 Nc3는 c3폰 때문에 바로 불가능합니다. …cxd4 cxd4 뒤 백 d4가 고립됩니다.',pieces:['백: f3 나이트가 중앙을 지지하고 b1 나이트는 c3폰 이동 뒤 또는 d2 경로를 찾습니다. 비숍·룩은 d4 공간을 활동으로 바꿉니다.','흑: f6 나이트·d5 퀸이 중앙을 압박합니다. 퀸이 쫓기기 전 전개를 마치고 교환 후 d5 봉쇄를 찾습니다.']});
set('french-tarrasch',{purpose:'Nd2로 …Bb4 핀을 피하고 c폰의 자유를 유지합니다. 현재 …c5 exd5 exd5형은 열린 활동과 흑 고립 d폰 가능성을 다룹니다. …Nf6 e5의 닫힌 사슬형은 별도입니다.',structure:'백 d4 대 흑 c5/d5이며 흑 d5는 아직 고립되지 않았습니다. dxc5 Bxc5 뒤 고립 d5가 되면 백 봉쇄·흑 …d4 해방이 중요해집니다. 백 Nd2가 c1 비숍을 막아 전개 혼잡을 해결해야 합니다.',pieces:['백: d2 나이트는 핀을 피하지만 c1 비숍을 막습니다. f3 나이트·비숍을 전개하고 중앙 룩으로 d5를 압박합니다.','흑: 중앙 d5/c5가 기물 공간을 줍니다. c폰 교환 후에는 활동 말과 …d4 돌파가 고립폰의 보상입니다.']});
set('kings-indian',{structure:'현재 백 c4–d4–e4 대 흑 d6–e5 긴장입니다. 백 d5 후에만 닫혀 백 c5/흑 …f5의 전형적인 양 날개 싸움이 됩니다. dxe5 교환형에서는 룩·중앙 활동이 우선입니다.'});
set('four-knights',{pieces:['백: b5 비숍은 c6 나이트를 묶어 e5 수비를 시험합니다. c3/f3 나이트가 e4와 돌파를 지원하고 c1 비숍은 d폰 이동으로 풉니다.','흑: b4 비숍은 c3 나이트를 핀해 e4 수비에 영향을 줍니다. 중앙을 열기 전 핀과 킹 안전을 확인합니다.']});
set('trompowsky',{purpose:'Bg5로 f6 나이트를 압박해 비숍 교환·폰 손상 또는 템포의 다른 구조를 선택합니다. 현재 …Ne4 Bf4는 비숍을 보존한 중앙 싸움이고 흑은 …d5로 e4 나이트를 지지합니다.',structure:'백 d4/e3 대 흑 d5와 e4 나이트입니다. c3/f폰이 아직 움직이지 않아 런던·스톤월 사슬은 아닙니다. 백 c4/e4, 흑 …c5가 구조를 바꿉니다.',pieces:['백: f4 어두운 칸 비숍은 사슬 밖에 있습니다. 나이트·밝은 칸 비숍 전개가 먼저이며 Nd2는 e4 나이트 압박을 돕습니다.','흑: e4 나이트는 d5의 지지를 받습니다. 다른 말 전개와 …c5로 중앙을 압박하며 나이트만 반복해 움직이지 않습니다.']});
set('english',{structure:'백 c폰과 흑 d폰이 교환되어 백 반열린 c열·흑 반열린 d열이 생겼습니다. 흑 e5는 공간 거점, 백 g2 비숍·Nc3는 d5 나이트를 압박합니다. 백 d4/b4, 흑 중앙 활동을 구조에 맞춰 선택합니다.'});
set('queens-indian',{purpose:'흑 b7 비숍·f6 나이트로 e4를 통제해 백의 확장을 늦춥니다. 백 g2 비숍·d4/c4 공간과 다투며 …d5/…c5가 대각선 활동을 결정합니다.',structure:'백 c4–d4/g3 대 흑 e6/b6입니다. 흑 d폰은 d7에 남아 구조가 유보되었습니다. …d5는 중앙 안정성을 주지만 b7 비숍을 막고 …c5는 d4를 공격하며 대각선을 바꿉니다.',pieces:['백: g2 비숍·f3 나이트가 중앙을 압박합니다. c1 비숍·b1 나이트를 전개해 e4를 준비합니다.','흑: b7 밝은 칸 비숍·f6 나이트가 e4를 통제합니다. …d5 이후 막히면 …c5와 교환으로 풀며 룩은 중앙 파일을 선택합니다.'],targets:['백: e4 확장·중앙 → 나이트·g2 비숍·폰 → 공간과 활동.','흑: e4 통제·d4 → Bb7·Nf6·…c5 → 확장 억제와 균형.']});
set('larsen',{pieces:['백: b2 어두운 칸 비숍은 e3폰에 가릴 수 있어 c4/f4/e폰 이동으로 풉니다. b5 밝은 칸 비숍은 c6 나이트를 압박해 e5 수비를 시험합니다.','흑: 중앙 나이트·비숍은 e5–d5 공간을 지킵니다. 중앙 교환이 b2 비숍 대각선을 열어 주는 결과도 계산합니다.']});
set('kia',{structure:'현재 백 d3/g3 대 흑 d5/e6이며 백 e폰은 아직 e2입니다. e4 이후 사슬·교환·긴장 구조 중 선택합니다. e5로 안정된 사슬을 만든 경우에만 왕측 기동을 검토합니다.'});
for(const id of ['vienna','vienna-gambit'])lessons[id].references=[['Vienna Game','https://www.chess.com/openings/Vienna-Game']];
lessons.ruy.references=[['Ruy Lopez','https://www.chess.com/openings/Ruy-Lopez-Opening']];
set('fried-liver',{purpose:'백은 5…Nxd5라는 특정 응수에 Nxf7 나이트 희생으로 흑 킹을 중앙에 끌어냅니다. 비숍·퀸·나이트 전개에 체크와 d5 수비 말 공격을 결합하는 전술전입니다. 흑은 공격 교환과 킹 탈출로 재료 이점을 지키려 합니다.'});
set('latvian',{purpose:'흑은 …f5로 e4에 반격하려 하지만 Nxe5로 중앙 폰을 잃고 퀸을 일찍 전개합니다. 흑의 활동과 f2 위협에 백은 중앙 공간·전개 템포·약해진 킹 대각선을 활용합니다. 함정과 충분한 보상은 별개입니다.',structure:'백 나이트가 e5폰을 잡고 c4로 돌아와 백 e4–d4 중앙이 남습니다. 흑 e폰은 사라지고 f5–d6가 중앙을 받칩니다. 흑 킹 대각선이 약하고 전개가 늦어 백의 열린 중앙 활동이 중요합니다. 백 e5/d5와 흑 …fxe4가 구조를 바꿉니다.',pieces:['백: c4 나이트는 중앙·d6를 겨냥하지만 추가 이동보다 왕측 비숍·퀸측 나이트 전개와 킹 안전이 중요합니다. 중앙 룩·비숍은 흑 전개 지연을 활용합니다.','흑: f6 퀸은 f2/e5를 겨냥하지만 백 전개 수에 공격받을 수 있습니다. 나이트·비숍 전개와 킹 안전을 갖추지 않으면 폰 희생의 활동 보상이 부족합니다.'],targets:['백: 중앙 흑 킹·퀸 → 전개 수·비숍·중앙 룩 → 템포와 재료 이점.','흑: f2·백 e4 → Qf6·f5폰·전개 기물 → 활동과 중앙 폰 회복.'],counters:['흑의 …fxe4: 백의 중앙 거점을 없애려 합니다. 백은 되잡기와 열린 f열·퀸 체크를 확인합니다.','백의 중앙 전진·퀸 공격: 흑의 전개 지연을 템포로 이용합니다. 흑은 폰 회복보다 왕측 전개·킹 안전을 우선해야 합니다.']});
set('bird',{ideas:['f4는 e5를 통제하지만 e1–h4 대각선 수비를 줄입니다.','b2 비숍은 자기 e3폰에 가릴 수 있어 e4/c4와 연결합니다.','왕측 공격은 흑 …e5/…c5 중앙 반격을 견딜 때 준비합니다.'],counters:['흑의 …e5: 백 f4와 중앙을 교환해 공격 기반을 줄입니다. 백은 중앙 교환 뒤 킹 대각선·비숍 선을 계산합니다.','흑의 …c5: d4 구축을 견제하고 퀸측 공간을 얻습니다. 백은 c/e폰 돌파와 중앙 수비를 선택합니다.']});
set('mikenas',{ideas:['백 d5는 나이트를 쫓아 공간과 전개 시간을 얻습니다.','흑 나이트 반복 이동은 중앙 돌파와 전개로 보상해야 합니다.','백은 추가 폰 전진보다 이미 얻은 공간을 지키고 기물을 꺼냅니다.'],counters:['흑의 …e5: 백 d5 공간을 봉쇄하고 중앙 거점을 만듭니다. 백은 폰 전진 뒤 약한 칸·기물 경로를 다시 판단합니다.','흑의 …e6/…d6: 전진 중앙을 공격하려 합니다. 백은 유지·교환 뒤 열린 선과 킹 안전을 확인합니다.']});
set('qga',{plans:[['d4/e3 중앙·회복한 c4폰','나이트·c1 비숍·중앙 룩 개선','e4 또는 교환 후 d5 준비','중앙·흑 전개','중앙 봉쇄 말 교환','활성 공격 말 전부 교환 피하기','안정된 중앙과 활동'],['c5/e6 반격 구조','나이트·비숍·중앙 룩 전개','…cxd4와 중앙 돌파 검토','d4','백의 활성 중앙 말 교환','중앙 압박 말 보존','공간 균형 또는 고립폰 압박']]});
set('alapin',{plans:[['c3–d4 중앙','b1 나이트 경로·비숍 전개','교환 뒤 d5 또는 중앙 유지','중앙·흑 퀸','중앙 봉쇄 말 교환','중앙 활동 말 일괄 교환 피하기','활동적인 중앙'],['c5 긴장·d5 퀸','퀸 안전·왕측 전개','…cxd4 검토','d4','백 중앙 공격 말 교환','중앙 봉쇄 말 보존','중앙 균형 또는 고립폰 봉쇄']]});
set('closed-sicilian',{pieces:['백: g2 밝은 칸 비숍은 d3/e4와 같은 색 폰에 제한될 수 있습니다. f4와 중앙 교환이 대각선을 바꿉니다. 나이트·어두운 칸 비숍을 먼저 전개하고 왕측 공격을 준비합니다.','흑: g7 비숍·퀸측 나이트·룩은 …b5/…d5를 지원합니다. 아직 c폰이 남아 열린 c열 룩 공격을 현재 사실로 가정하지 않습니다.']});
}
